 "content": "from collections import Counter


def transform(grid):
    """Restore a zero-masked cyclic staircase.

    In the staircase, cells left of the main diagonal use sequence S at their
    column; cells on/right of it use S at the preceding column. Infer the
    shortest sequence period consistent with the visible cells.
    """
    h, w = len(grid), len(grid[0])
    best = None
    for period in range(1, 10):
        buckets = [Counter() for _ in range(period)]
        for r in range(h):
            for c in range(w):
                v = grid[r][c]
                if v:
                    idx = c if c < r else c - 1
                    buckets[idx % period][v] += 1
        seq = [bucket.most_common(1)[0][0] if bucket else None for bucket in buckets]
        errors = sum(
            1
            for r in range(h)
            for c in range(w)
            if grid[r][c]
            and seq[((c if c < r else c - 1) % period)] != grid[r][c]
        )
        candidate = (errors, period, seq)
        if best is None or candidate[:2] < best[:2]:
            best = candidate
    errors, period, seq = best
    if errors:
        raise ValueError(f"Visible cells do not fit a cyclic staircase (errors={errors})")
    return [
        [seq[((c if c < r else c - 1) % period)] for c in range(w)]
        for r in range(h)
    ]
